from fastapi import FastAPI
from pydantic import BaseModel, field_validator

app = FastAPI()

class Item(BaseModel):
    name: str
    quantity: int
    price: float

    def total(self) -> float:
        return self.quantity * self.price

    @field_validator("name")
    @classmethod
    def _validate_name(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("name must be stripped and nonempty")
        return v

    @field_validator("quantity")
    @classmethod
    def _validate_quantity(cls, v: int) -> int:
        if v < 1 or v > 100:
            raise ValueError("quantity must be in range 1..100")
        return v

    @field_validator("price")
    @classmethod
    def _validate_price(cls, v: float) -> float:
        if v < 0:
            raise ValueError("price must be >= 0")
        return v

@app.post("/items", status_code=201)
def create_item(item: Item):
    return {"name": item.name, "total": item.total}

